and T2.ENTRUST_ID in
#{item}
and T2.ENTRUST_ID in
#{item}
WHERE T1.TRADE_STATUS = '01' AND (T1.IS_CANCEL IS NULL OR T1.IS_CANCEL = 'N') and NOT EXISTS ( SELECT 1 FROM TRDQUTO_MATCH_INFO T3 WHERE T3.PRE_TRADE_ID = T1.TOTLE_TRADE_ID) UNION ALL SELECT T2.ENTRUST_ID FROM IBU_QUOTE_BOND T1 INNER JOIN IBU_QUOTE_ETR_RE T2 ON T1.QUOTE_ID = T2.QUOTE_ID
and T2.ENTRUST_ID in
#{item}
and T2.ENTRUST_ID in
