and T1.TRADE_STATUS not in
#{item}
)

SELECT EXERCISE_DATE , ACT_EXERCISE_DATE, EXERCISE_PRICE FROM FIN_EXERCISE_PLAN T1 WHERE FINPROD_ID = #{finprodId}
AND EXERCISE_TYPE = #{exerciseType}
AND EXISTS ( SELECT 1 FROM ( SELECT MIN(EXERCISE_DATE)EXERCISE_DATE, FINPROD_ID FROM FIN_EXERCISE_PLAN WHERE EXERCISE_DATE >= to_date(#{platDate}, 'yyyy-MM-dd') GROUP BY FINPROD_ID) T2 WHERE T2.EXERCISE_DATE = T1.EXERCISE_DATE AND T2.FINPROD_ID = T1.FINPROD_ID )

SELECT COUNT(1) FROM  ETR_ENTRUST WHERE ENTRUST_STATUS != #{entrustStatus}

    and ENTRUST_ID in

        #{item}

SELECT T5.ENTRUST_ID, nvl(T4.OUR_SHARE_AMT,0)*100 usedOurShareAmt, nvl(T4.LENDIN_SHARE_AMT,0)*100 usedLendinShareAmt, nvl(T5.OUR_ENT_NUM,0)*100 ourEntNum, nvl(T5.LENDIN_ENT_NUM,0)*100 lendinEntNum FROM ETR_ENTRUST_ADD T5 LEFT JOIN ( SELECT T3.ENTRUST_ID, SUM(T3.OUR_SHARE_AMT) OUR_SHARE_AMT, SUM(T3.LENDIN_SHARE_AMT) LENDIN_SHARE_AMT FROM ( SELECT T1.ENTRUST_ID, T2.OUR_SHARE_AMT, T2.LENDIN_SHARE_AMT FROM REG_FIN_PRODUCT_DEAL T1 LEFT JOIN REG_FIN_PRODUCT_DEAL_ADD T2 ON T2.TRADE_ID = T1.TRADE_ID WHERE exists( SELECT 1 FROM REG_FIN_PRODUCT_DEAL_TOTAL T3 WHERE T3.TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID AND T3.TRADE_STATUS = '01' AND (T3.IS_CANCEL = 'N' OR T3.IS_CANCEL IS NULL) ) UNION ALL SELECT T1.ENTRUST_ID, T2.OUR_SHARE_AMT, T2.LENDIN_SHARE_AMT FROM WFL_REG_FIN_PRODUCT_DEAL T1 LEFT JOIN WFL_REG_FIN_PRODUCT_DEAL_ADD T2 ON T2.TRADE_ID = T1.TRADE_ID
T1.WORKFLOW_ID != #{workflowId}
union all SELECT ENTRUST_ID, OUR_SHARE_AMT, LENDIN_SHARE_AMT FROM IBU_QUOTE_ETR_RE T1 WHERE EXISTS ( SELECT 1 FROM IBU_QUOTE_BOND T2 WHERE T2.QUOTE_ID = T1.QUOTE_ID
and T2.QUOTE_ID != #{quoteId}
and T2.TRADE_STATUS in
#{item}
) AND NOT EXISTS ( SELECT 1 FROM WFL_IBU_QUOTE_BOND2 T3 WHERE T3.QUOTE_ID = T1.QUOTE_ID) UNION ALL SELECT ENTRUST_ID, OUR_SHARE_AMT, LENDIN_SHARE_AMT FROM WFL_IBU_QUOTE_ETR_RE T1
T1.WORKFLOW_ID != #{workflowId}
) T3 GROUP BY ENTRUST_ID) T4 ON T5.ENTRUST_ID = T4.ENTRUST_ID
and T5.ENTRUST_ID in
#{item}
